document.addEventListener("DOMContentLoaded",()=>{initUruExplorer(),initKhalasiCalculator(),initGalleryModal(),initBookmarkButton(),initMobileMenu()});const uruData={keel:{title:"1. Keel Laying (Eratavu)",badge:"Structural Backbone",desc:"The construction of an Uru begins with the laying of the Eratavu (keel). Carved from a massive, flawless trunk of Nilambur Teak, the keel serves as the primary spine of the entire ship. Master shipwrights (Maistry) perform ritual measurements using wooden rods (kolu) to ensure perfect symmetry.",img:"../assets/beypore_uru_shipbuilding.png",specs:[{label:"Material",val:"Nilambur Teak"},{label:"Length Range",val:"60 – 140 Feet"},{label:"Joinery",val:"Lap & Mortise"},{label:"Est. Lifespan",val:"100+ Years"}]},hull:{title:"2. Hull Planking (Patti)",badge:"No Blueprints Required",desc:"Planking involves shaping dense teak boards along the keel skeleton. Craftsmen use heat from controlled wood fires and natural fish oil to steam and bend the thick planks. Each plank is secured using hand-forged copper nails, preventing rust and galvanic corrosion in sea water.",img:"../assets/beypore_uru_shipbuilding.png",specs:[{label:"Fastening",val:"Pure Copper Nails"},{label:"Shaping Method",val:"Steam & Fish Oil"},{label:"Design Blueprint",val:"Oral Precision (Kolu)"},{label:"Plank Thickness",val:"2 – 4 Inches"}]},caulking:{title:"3. Caulking & Sealing (Kalapathi)",badge:"100% Water Tight",desc:"To render the hull completely impermeable, Khalasi artisans drive coconut coir fiber soaked in natural plant resin and boiled sardine oil between every plank seam (Kalapathi). This ancient technique swells when submerged, creating an impenetrable organic seal.",img:"../assets/beypore_port_banner.png",specs:[{label:"Sealing Material",val:"Coir & Resin"},{label:"Waterproof Level",val:"Hermetic Seal"},{label:"Maintenance",val:"Annual Fish-Oil Coat"},{label:"Eco Footprint",val:"Zero Synthetics"}]},rigging:{title:"4. Masts & Sails (Pai & Maram)",badge:"Oceanic Trade Propulsion",desc:"Once the hull is complete, tall wooden masts (Maram) are stepped into the keelson. Triangular lateen sails (Pai) crafted from heavy cotton canvas are rigged using high-tensile coir ropes, allowing the Uru to navigate monsoon trade winds across the Arabian Sea to the Persian Gulf.",img:"../assets/beypore_port_banner.png",specs:[{label:"Masts Count",val:"2 – 3 Teak Masts"},{label:"Sail Pattern",val:"Lateen Dhow Canvas"},{label:"Rigging Cordage",val:"Braided Coir"},{label:"Sailing Speed",val:"8 – 12 Knots"}]},khalasi:{title:"5. Khalasi River Launch (Tambu)",badge:"Legendary Mechanical Engineering",desc:"The Beypore Khalasis use wooden winches (Tambu), heavy pulleys, iron cables, and coir ropes to launch massive multi-hundred-ton Urus into the Chaliyar River. Operating solely on physical lever principles, rhythm, and teamwork, they move giant vessels without modern cranes.",img:"../assets/beypore_khalasi_rigging.png",specs:[{label:"Mechanism",val:"Tambu (Wooden Winch)"},{label:"Mechanical Gain",val:"10:1 Ratio"},{label:"Modern Cranes",val:"Zero Powered Cranes"},{label:"Guild Legacy",val:"Centuries Old"}]}};function initUruExplorer(){const e=document.querySelectorAll(".uru-tab-btn"),t=document.getElementById("uru-panel-img"),a=document.getElementById("uru-panel-title"),n=document.getElementById("uru-panel-badge"),i=document.getElementById("uru-panel-desc"),l=document.getElementById("uru-panel-specs");e.length&&e.forEach(s=>{s.addEventListener("click",()=>{e.forEach(e=>e.classList.remove("active")),s.classList.add("active");const r=s.getAttribute("data-stage"),o=uruData[r];o&&(a.textContent=o.title,n.textContent=o.badge,i.textContent=o.desc,t.src=o.img,t.alt=o.title,l.innerHTML=o.specs.map(e=>`\n          <div class="uru-spec-item">\n            <span class="uru-spec-label">${e.label}</span>\n            <span class="uru-spec-val">${e.val}</span>\n          </div>\n        `).join(""))})})}function initKhalasiCalculator(){const e=document.getElementById("khalasi-weight-slider"),t=document.getElementById("weight-val"),a=document.getElementById("res-men"),n=document.getElementById("res-ratio"),i=document.getElementById("res-tension"),l=document.getElementById("res-time");function s(){const s=parseInt(e.value,10);t.textContent=`${s} Tons`;const r=Math.round(.38*s)+12,o=Math.round(s/16)+4,d=(1.75*s).toFixed(1),c=(s/28+1.5).toFixed(1);a.textContent=`${r} Craftsmen`,n.textContent=`1:${o}`,i.textContent=`${d} kN`,l.textContent=`${c} hrs`}e&&(e.addEventListener("input",s),s())}function initGalleryModal(){const e=document.querySelectorAll(".port-gallery-item"),t=document.getElementById("port-modal"),a=document.getElementById("port-modal-close"),n=document.getElementById("modal-title"),i=document.getElementById("modal-heading"),l=document.getElementById("modal-description");t&&(e.forEach(e=>{e.addEventListener("click",()=>{const a=e.getAttribute("data-title")||"Beypore Highlight",s=e.getAttribute("data-desc")||"",r=e.querySelector("h4")?e.querySelector("h4").textContent:"";n.textContent=a,i.textContent=r,l.textContent=s,t.classList.add("active"),t.setAttribute("aria-hidden","false")})}),a&&a.addEventListener("click",()=>{t.classList.remove("active"),t.setAttribute("aria-hidden","true")}),t.addEventListener("click",e=>{e.target===t&&(t.classList.remove("active"),t.setAttribute("aria-hidden","true"))}))}function initBookmarkButton(){const e=document.querySelector(".journey-bookmark-btn");if(!e)return;const t=e.getAttribute("data-bookmark-id")||"beypore-port-main";JSON.parse(localStorage.getItem("savedJourneys")||"[]").includes(t)&&(e.setAttribute("aria-pressed","true"),e.innerHTML="♥ Saved in Journey"),e.addEventListener("click",()=>{let a=JSON.parse(localStorage.getItem("savedJourneys")||"[]");a.includes(t)?(a=a.filter(e=>e!==t),e.setAttribute("aria-pressed","false"),e.innerHTML="♡ Save to Journey"):(a.push(t),e.setAttribute("aria-pressed","true"),e.innerHTML="♥ Saved in Journey"),localStorage.setItem("savedJourneys",JSON.stringify(a))})}function initMobileMenu(){const e=document.getElementById("menu-toggle"),t=document.getElementById("nav-menu");e&&t&&e.addEventListener("click",()=>{t.classList.toggle("active"),e.classList.toggle("active")})}